package dev.smpcristalix.pvpcombat.service;
import dev.smpcristalix.pvpcombat.config.PvPCombatSettings;import dev.smpcristalix.pvpcombat.data.PlayerProfile;import org.bukkit.entity.Player;
/** Правила прокачки, независимые от GUI. */
public final class UpgradeService{private final StatsService stats;private final ShardService shards;private PvPCombatSettings settings;public UpgradeService(StatsService s,ShardService h,PvPCombatSettings c){stats=s;shards=h;settings=c;}public void reload(PvPCombatSettings s){settings=s;}public Result upgrade(Player player,Stat stat){PlayerProfile p=stats.profile(player.getUniqueId());stats.clamp(p);if(!can(p,stat))return new Result(false,"Характеристика уже на максимуме.");if(!shards.consumeOne(player))return new Result(false,"У тебя нет Осколка.");switch(stat){case DAMAGE->p.damageLevel(p.damageLevel()+1);case HEALTH->p.healthStep(p.healthStep()+1);case SPEED->p.speedLevel(p.speedLevel()+1);case SATIETY->p.satietyLevel(p.satietyLevel()+1);case ABILITY->p.abilityLevel(p.abilityLevel()+1);}stats.apply(player);return new Result(true,"Характеристика улучшена.");}private boolean can(PlayerProfile p,Stat s){return switch(s){case DAMAGE->p.damageLevel()<settings.damageLevels();case HEALTH->p.healthStep()<stats.maxHealthStep();case SPEED->p.speedLevel()<settings.speedLevels();case SATIETY->p.satietyLevel()<settings.satietyLevels();case ABILITY->p.abilityLevel()<settings.maxAbilityLevel();};}public enum Stat{DAMAGE,HEALTH,SPEED,SATIETY,ABILITY}public record Result(boolean success,String message){}}
